}

Method.Source:
public static AVADAIServer findServer(AVADAIServerId _serverId, boolean _forUpdate = false)
{
    AVADAIServer dmsServer;

    if (_serverId)
    {
        dmsServer.selectForUpdate(_forUpdate);

        select firstonly dmsServer
            where dmsServer.ServerId == _serverId;
    }

    return dmsServer;
}

/// <summary>
/// Checks if records exists in table.
/// </summary>
/// <param name = "AVADAIServerId">ServerId.</param>
/// <returns> <c>Boolean</c> object.</returns>
public static boolean exist(AVADAIServerId _serverId )
{
    boolean         found;
    AVADAIServer    avaDAIServer;

    if(_serverId)
    {
        found = (select firstonly RecId from avaDAIServer where avaDAIServer.ServerId == _serverId).RecId != 0;
    }

    return found;
}

/// <summary>
/// Selects records based on serverId.
/// </summary>
/// <param name = "FieldName">fieldname.</param>
/// <param name = "integer">index</param>
public void modifiedFieldValue(FieldName _fieldName, int _arrayIndex = 1)
{
    super(_fieldName, _arrayIndex);

    switch (_fieldName)
    {
        case fieldStr(AVADAIServer, LinkOpenType):
            if (this.LinkOpenType == AVADAILinkOpenType::DirectUrl)
            {
                this.resetDirectUrlIrrelavantFields();
            }
            break;

        case fieldStr(AVADAIServer, InsertCompany):
            if (this.InsertCompany == NoYes::No)
            {
                this.EscapeStrCompany = '';
            }
            break;
    }
}

/// <summary>
/// Validate while inserting.
/// </summary>
public boolean validateWrite()
{
    boolean ret = super();

    if (this.LinkOpenType == AVADAILinkOpenType::DocumentId)
    {
        if (!this.OpenDocUrl)
        {
            ret = checkFailed(strFmt("@SYS50104", fieldPName(AVADAIServer, OpenDocUrl)));
        }

        if (!this.EscapeStr)
        {
            ret = checkFailed(strFmt("@SYS50104", fieldPName(AVADAIServer, EscapeStr)));
        }

        if (this.InsertCompany == NoYes::Yes && !this.EscapeStrCompany)
        {
            ret = checkFailed(strFmt("@SYS50104", fieldPName(AVADAIServer, EscapeStrCompany)));
        }
    }

    return ret;
}

/// <summary>
/// insert records.
/// </summary>
public void insert()
{
    if (this.LinkOpenType == AVADAILinkOpenType::DirectUrl)
    {
        this.resetDirectUrlIrrelavantFields();
    }

    if (this.InsertCompany == NoYes::No)
    {
        this.EscapeStrCompany = '';
    }

    super();
}

/// <summary>
/// Update records.
/// </summary>
public void update()
{
    if (this.LinkOpenType == AVADAILinkOpenType::DirectUrl)
    {
        this.resetDirectUrlIrrelavantFields();
    }

    if (this.InsertCompany == NoYes::No)
    {
        this.EscapeStrCompany = '';
    }

    super();
}

/// <summary>
/// reset fields.
/// </summary>
private void resetDirectUrlIrrelavantFields()
{
    this.OpenDocUrl         = '';
    this.EscapeStr          = '';
    this.InsertCompany      = NoYes::No;
    this.EscapeStrCompany   = '';
}
